#!/bin/bash
# Flash script for theSpeaker (3 boards)
# Auto-generated by Embedded Generator
# Erases flash + NVS before programming for a clean start

set -e

PORT="${1:-/dev/ttyUSB0}"
BAUD="${2:-115200}"

# Check if ESP-IDF is set up
if [ -z "$IDF_PATH" ]; then
    echo "ERROR: ESP-IDF environment not set up."
    echo "Please run: . $HOME/esp/esp-idf/export.sh"
    exit 1
fi

echo "========================================"
echo " Erasing flash and NVS (clean start)"
echo "========================================"
python3 -m esptool --port "$PORT" --baud "$BAUD" erase_flash
sleep 1

echo ""
echo "========================================"
echo " Flashing theSpeaker (3 boards)"
echo "========================================"
idf.py -p "$PORT" -b "$BAUD" flash

echo ""
echo "Flash complete!"
echo "To monitor: ./monitor.sh $PORT"
